import './App.css';
import { useState } from "react";

function App() {
  const [rate, changeRate] = useState(0.0);
  const [inputValue, setInputValue] = useState("")
  const [errorValue, setErrorValue] = useState("")
  const [depositValue, setDepositValue] = useState("")
  const [depositError, setDepositError] = useState("")

  function errorHandling (e) {
        const inputGiven = e.target.value
        const error = "Invalid input: value must be greater than 0. Please try again.";
        <span className = "errorMessage">{error}</span>;

        if (inputGiven <= 0) {
            setErrorValue(error)
        }
        else {
            setErrorValue(null)
        }

        setInputValue (inputGiven)
    }
  return (
    <>
    <div className = "header"></div>
    <h1>MORTGAGE CALCULATOR</h1>
    <h2 className = "appExplanation">Add application description</h2>

    <div className = "allContent">
      <div className = "inputsArea">

        <h3>Scenarios</h3> 
        <div class="buttons">
          <button>First-Time Buyer Calculator</button>
          <button>Home Mover Calculator</button>
          <button>Remortgage Calculator</button>
          <button>Buy-to-Let Mortgage Tool</button>
        </div>

        <h3>Property details</h3>

        <div className = "inputs">
          <label htmlFor="propertyValue">Property Value</label>
          <input type="number" id="propertyValue" placeholder="e.g. 123,456"
          value={inputValue} onChange={errorHandling}/>
          {inputValue && <p className="errorMessage">{errorValue}</p>}
        </div>

        <div className = "inputs">
          <label htmlFor="depositAmount">Deposit Amount</label>
          <input type="number" id="depositAmount" placeholder="e.g. 50,000"
          value={inputValue} onChange={errorHandling}/>
          {inputValue && <p className="errorMessage">{errorValue}</p>}
        </div>


        <h3>Mortgage Details</h3> 

        <div className = "inputs">
          <label htmlFor="mortgageType">Mortgage Type</label>
          <select>
            <option>Select Type</option>
            <option>Fixed Rate</option>
            <option>Adjustable Rate</option>
            <option>Interest Only</option>
          </select>
        </div>


        <div className = "inputs">
          <label htmlFor="mortgageDuration">Mortgage Duration (years)</label>
          <input type="number" id="mortgageDuration" placeholder="e.g. 10"/>
        </div>

        <div className = "inputs">
          <div className = "InterestRateSlider">
            <h4>Interest Rate in %</h4>
            <input 
            type="range" 
            min="0" 
            max="100" 
            step="0.01"
            value={rate}
            onChange={(e) => changeRate(parseFloat(e.target.value))}
            />

            <input 
            type = "number"
            min="0" 
            max="100"
            step="0.01"
            value={rate}
            onChange={(e) => changeRate(parseFloat(e.target.value))}
            />
          </div>
        </div>

      </div>
      <div className = "resultsArea"></div>
    </div>

    </>
  );
}

export default App;
